-- =====================================================================
-- Fotografias do catalogo gravadas diretamente no banco como WebP
--
-- Gerado por seed/gerar_migration.py. Nao edite os bytes manualmente.
-- Os arquivos-fonte ficam em seed/imagens apenas para tornar a carga
-- reproduzivel; em runtime o front recebe somente /api/produtos/{id}/imagem.
-- =====================================================================

INSERT INTO tb_produto_imagens (produto_id, conteudo, tipo_conteudo,
                                tamanho_em_bytes, nome_arquivo, hash_sha256)
SELECT p.id,
       d.conteudo,
       'image/webp',
       octet_length(d.conteudo),
       d.nome_arquivo,
       encode(sha256(d.conteudo), 'hex')
  FROM (VALUES
    ('Banana Prata', '\'::bytea, 'banana-prata.webp'),
    ('Maçã Gala', '\'::bytea, 'maca-gala.webp'),
    ('Tomate Italiano', '\'::bytea, 'tomate-italiano.webp'),
    ('Batata Inglesa Lavada', '\'::bytea, 'batata-inglesa-lavada.webp'),
    ('Cebola Nacional', '\'::bytea, 'cebola-nacional.webp'),
    ('Cenoura', '\'::bytea, 'cenoura.webp'),
    ('Mamão Formosa', '\'::bytea, 'mamao-formosa.webp'),
    ('Limão Tahiti', '\'::bytea, 'limao-tahiti.webp'),
    ('Alface Crespa', '\'::bytea, 'alface-crespa.webp'),
    ('Abacaxi Pérola', '\'::bytea, 'abacaxi-perola.webp'),
    ('Refrigerante Cola 2L', '\'::bytea, 'refrigerante-cola-2l.webp'),
    ('Refrigerante Guaraná 2L', '\'::bytea, 'refrigerante-guarana-2l.webp'),
    ('Suco de Laranja 1L', '\'::bytea, 'suco-de-laranja-1l.webp'),
    ('Suco de Uva Integral 1L', '\'::bytea, 'suco-de-uva-integral-1l.webp'),
    ('Água Mineral 500ml', '\'::bytea, 'agua-mineral-500ml.webp'),
    ('Cerveja Pilsen Lata 350ml', '\'::bytea, 'cerveja-pilsen-lata-350ml.webp'),
    ('Picanha Bovina', '\'::bytea, 'picanha-bovina.webp'),
    ('Alcatra', '\'::bytea, 'alcatra.webp'),
    ('Coxão Mole', '\'::bytea, 'coxao-mole.webp'),
    ('Carne Moída Patinho', '\'::bytea, 'carne-moida-patinho.webp'),
    ('Filé de Peito de Frango', '\'::bytea, 'file-de-peito-de-frango.webp'),
    ('Frango Inteiro Congelado', '\'::bytea, 'frango-inteiro-congelado.webp'),
    ('Linguiça Toscana', '\'::bytea, 'linguica-toscana.webp'),
    ('Costela Suína', '\'::bytea, 'costela-suina.webp'),
    ('Pão Francês', '\'::bytea, 'pao-frances.webp'),
    ('Pão de Forma Integral', '\'::bytea, 'pao-de-forma-integral.webp'),
    ('Broa de Fubá', '\'::bytea, 'broa-de-fuba.webp'),
    ('Croissant Folhado', '\'::bytea, 'croissant-folhado.webp'),
    ('Rosca Doce Trançada', '\'::bytea, 'rosca-doce-trancada.webp'),
    ('Queijo Minas Frescal', '\'::bytea, 'queijo-minas-frescal.webp'),
    ('Presunto Cozido Fatiado', '\'::bytea, 'presunto-cozido-fatiado.webp'),
    ('Mussarela Fatiada', '\'::bytea, 'mussarela-fatiada.webp'),
    ('Arroz Branco Tipo 1 5kg', '\'::bytea, 'arroz-branco-tipo-1-5kg.webp'),
    ('Feijão Carioca 1kg', '\'::bytea, 'feijao-carioca-1kg.webp'),
    ('Açúcar Refinado 1kg', '\'::bytea, 'acucar-refinado-1kg.webp'),
    ('Sal Refinado 1kg', '\'::bytea, 'sal-refinado-1kg.webp'),
    ('Café Torrado e Moído', '\'::bytea, 'cafe-torrado-e-moido.webp'),
    ('Óleo de Soja 900ml', '\'::bytea, 'oleo-de-soja-900ml.webp'),
    ('Macarrão Espaguete 500g', '\'::bytea, 'macarrao-espaguete-500g.webp'),
    ('Farinha de Trigo 1kg', '\'::bytea, 'farinha-de-trigo-1kg.webp'),
    ('Leite Integral 1L', '\'::bytea, 'leite-integral-1l.webp'),
    ('Molho de Tomate 340g', '\'::bytea, 'molho-de-tomate-340g.webp'),
    ('Detergente Neutro 500ml', '\'::bytea, 'detergente-neutro-500ml.webp'),
    ('Sabão em Pó 1,6kg', '\'::bytea, 'sabao-em-po-1-6kg.webp'),
    ('Água Sanitária 2L', '\'::bytea, 'agua-sanitaria-2l.webp'),
    ('Amaciante Concentrado 2L', '\'::bytea, 'amaciante-concentrado-2l.webp'),
    ('Desinfetante 2L', '\'::bytea, 'desinfetante-2l.webp'),
    ('Papel Higiênico 12 rolos', '\'::bytea, 'papel-higienico-12-rolos.webp'),
    ('Esponja Multiuso 3un', '\'::bytea, 'esponja-multiuso-3un.webp'),
    ('Saco de Lixo 50L 30un', '\'::bytea, 'saco-de-lixo-50l-30un.webp'),
    ('Panetone Artesanal 750g', '\'::bytea, 'panetone-artesanal-750g.webp'),
    ('Sabão em Barra Antigo 200g', '\'::bytea, 'sabao-em-barra-antigo-200g.webp')
  ) AS d (nome, conteudo, nome_arquivo)
  JOIN tb_produtos p ON p.nome = d.nome
ON CONFLICT (produto_id) DO UPDATE SET
       conteudo = EXCLUDED.conteudo,
       tipo_conteudo = EXCLUDED.tipo_conteudo,
       tamanho_em_bytes = EXCLUDED.tamanho_em_bytes,
       nome_arquivo = EXCLUDED.nome_arquivo,
       hash_sha256 = EXCLUDED.hash_sha256,
       atualizado_em = now();

-- Depois da substituicao nao resta SVG no banco. O CHECK volta a refletir os
-- mesmos formatos raster aceitos pela aplicacao e impede SVG em qualquer
-- caminho de escrita, inclusive SQL executado fora das migrations.
ALTER TABLE tb_produto_imagens DROP CONSTRAINT ck_produto_imagens_tipo;

ALTER TABLE tb_produto_imagens ADD CONSTRAINT ck_produto_imagens_tipo CHECK (
    tipo_conteudo IN ('image/jpeg','image/png','image/webp','image/avif'));
